// Lead Ads fields depend on the questions in your form. Map the common names to our lead shape.
const d = $json.data || Object.fromEntries(($json.field_data || []).map(f => [f.name, (f.values || [])[0]]));
const pick = (...k) => k.map(x => d[x]).find(v => v !== undefined && v !== '') || '';
return [{ json: { source: 'facebook', name: pick('full_name', 'name'), phone: pick('phone_number', 'phone'),
  budget_raw: pick('budget', 'what_is_your_budget?'), area_raw: pick('area', 'preferred_area', 'city'),
  unit_type: pick('unit_type', 'property_type'), timeline: pick('timeline', 'when_do_you_want_to_buy?'), message: '', wa_phone_id: '' } }];

// Free text from WhatsApp: ask Gemini to pull out the lead fields as JSON. Code validates them next.
const m = $json.messages[0];
const prompt = 'Extract real-estate lead details from this Egyptian customer message. Return JSON with keys: ' +
  'name, budget (as written), area, unit_type (apartment|villa|""), timeline (now|within 3 months|within 6 months|just browsing|""). ' +
  'Use "" when not mentioned. Do not guess. Message: <<<' + m.text.body + '>>>';
return [{ json: { prompt, source: 'whatsapp', phone: m.from, message: m.text.body,
  contact_name: $json.contacts?.[0]?.profile?.name || '', wa_phone_id: $json.metadata?.phone_number_id || '' } }];

// Parse the model's JSON. If the AI failed or returned junk, keep the raw message: validation will send it to review.
const base = $('Prepare AI Extraction').item.json;
let f = {};
try { f = JSON.parse(($json.candidates?.[0]?.content?.parts || []).map(p => p.text).join('')); } catch (e) { f = {}; }
return [{ json: { source: 'whatsapp', name: f.name || base.contact_name, phone: base.phone, budget_raw: f.budget || '', area_raw: f.area || '',
  unit_type: f.unit_type || '', timeline: f.timeline || '', message: base.message, wa_phone_id: base.wa_phone_id, ai_ok: Object.keys(f).length > 0 } }];

// Never trust form input or AI output. Normalize, check, and list every problem.
const j = $json;
const AREAS = { 'new cairo': 'New Cairo', 'التجمع': 'New Cairo', 'القاهرة الجديدة': 'New Cairo', 'sheikh zayed': 'Sheikh Zayed', 'زايد': 'Sheikh Zayed',
  '6th of october': '6th of October', 'october': '6th of October', 'اكتوبر': '6th of October', 'أكتوبر': '6th of October',
  'nasr city': 'Nasr City', 'مدينة نصر': 'Nasr City', 'new capital': 'New Capital', 'العاصمة': 'New Capital', 'obour': 'Obour', 'العبور': 'Obour' };
const en = s => String(s || '').replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/٫/g, '.').replace(/٬/g, ',');
const phone = en(j.phone).replace(/[\s\-()]/g, '').replace(/^(\+20|0020|20)(?=1)/, '0');
function budget(raw) {
  const s = en(raw).toLowerCase().replace(/,/g, '').trim(); const m = s.match(/\d+(\.\d+)?/); if (!m) return null;
  let n = parseFloat(m[0]);
  if (/million|مليون|\dm\b|\sm\b/.test(s)) n *= 1e6; else if (/thousand|ألف|الف|\dk\b/.test(s)) n *= 1e3; else if (n < 100) n *= 1e6;
  return Math.round(n);
}
const b = budget(j.budget_raw);
const areaKey = Object.keys(AREAS).find(k => String(j.area_raw || '').toLowerCase().includes(k));
const problems = [];
if (!/^01[0125]\d{8}$/.test(phone)) problems.push('phone is not a valid Egyptian mobile');
if (b === null) problems.push('budget missing'); else if (b < 500000 || b > 200000000) problems.push('budget ' + b + ' EGP looks wrong');
if (!areaKey) problems.push('area not recognised');
const valid = /^01[0125]\d{8}$/.test(phone) && b !== null && b >= 500000 && b <= 200000000;
return [{ json: { ...j, phone, budget_egp: b, area: areaKey ? AREAS[areaKey] : '', unit_type: ['apartment', 'villa'].includes(j.unit_type) ? j.unit_type : '',
  timeline: j.timeline || 'unknown', valid, problems } }];

// Rule-based score (explainable for sales) + up to 3 available units in the area and within budget +10%.
const l = $('Validate Lead').first().json;
const units = $input.all().map(i => i.json).filter(u => u.unit_id);
const tl = { 'now': 40, 'within 3 months': 25, 'within 6 months': 10, 'just browsing': 0 }[l.timeline] ?? 5;
const fits = units.filter(u => (!l.area || u.area === l.area) && (!l.unit_type || u.type === l.unit_type) && Number(u.price_egp) <= l.budget_egp * 1.1)
  .sort((a, b) => Number(b.price_egp) - Number(a.price_egp)).slice(0, 3);
const score = Math.min(100, tl + (fits.length ? 30 : 0) + (l.area ? 10 : 0) + (l.unit_type ? 5 : 0) + (l.source === 'whatsapp' ? 15 : l.source === 'website' ? 10 : 5));
const tier = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
const id = 'L-' + $now.setZone('Africa/Cairo').toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const list = fits.map(u => '• ' + u.unit_id + ' · ' + u.bedrooms + ' bd ' + u.type + ' in ' + u.area + ' · ' + Number(u.price_egp).toLocaleString('en-US') + ' EGP · ' + u.link).join('\n');
return [{ json: { ...l, lead_id: id, score, tier, matched_units: fits.map(u => u.unit_id).join(','), units_text: list || 'No exact match yet; an advisor will send options.' } }];

